def cleanup_intermediate_dirs(results_folder: str, logger) -> None:
    """Delete intermediate crop/mask directories to save disk inodes/space.

    Only removes Crops, Deconv_crops, Masks, and Images — the per-particle
    intermediate outputs no longer needed once a profile is fully processed.
    Keeps Data (segmentation CSVs) and EcoTaxa (the classified TSV). Guarded
    on the EcoTaxa TSV existing so nothing is deleted for an incomplete profile.
    """
    ecotaxa_dir = os.path.join(results_folder, "EcoTaxa")
    tsvs = glob(os.path.join(ecotaxa_dir, "*_ecotaxa.tsv")) if os.path.isdir(ecotaxa_dir) else []
    if not tsvs:
        logger.log("  Cleanup skipped: no EcoTaxa TSV found (keeping intermediates).")
        return
    for sub in ("Crops", "Deconv_crops", "Masks", "Images"):
        path = os.path.join(results_folder, sub)
        if os.path.isdir(path):
            try:
                shutil.rmtree(path)
                logger.log(f"  Cleaned intermediate dir: {sub}")
            except OSError as e:
                logger.log(f"  WARNING: could not remove {sub}: {e}")


