  const show=e=>{tip.textContent=text;tip.style.opacity="1";if(e&&e.clientX)move(e)};
  const move=e=>{tip.style.left=e.clientX+"px";tip.style.top=e.clientY+"px"};
  el.addEventListener("pointerenter",show); el.addEventListener("pointermove",move);
  el.addEventListener("pointerleave",()=>tip.style.opacity="0");
  el.addEventListener("focus",()=>{const r=el.getBoundingClientRect();
    tip.textContent=text;tip.style.opacity="1";
    tip.style.left=(r.left+r.width/2)+"px";tip.style.top=r.top+"px"});
  el.addEventListener("blur",()=>tip.style.opacity="0");
}
function renderStage(id){
  const host=document.getElementById(id);
  STAGES[id].forEach(row=>{
    const total=Object.values(row.d).reduce((a,b)=>a+b,0);
    const wrap=document.createElement("div"); wrap.className="bar-row";
    wrap.innerHTML=`<div class="bar-label"><div class="bar-name">${row.name}
      <span>· ${row.sub}</span></div><div class="bar-total">${fmt(total)}</div></div>`;
    const bar=document.createElement("div"); bar.className="bar";
    ORDER.filter(t=>row.d[t]).forEach(t=>{
      const v=row.d[t], pct=v/total*100;
      const seg=document.createElement("div");
      seg.className="seg"+(DARKINK.has(t)?" on-light":"");
      seg.style.flex=v+" 0 0"; seg.style.background=colorOf(t);
      seg.tabIndex=0; seg.setAttribute("role","img");
      seg.setAttribute("aria-label",`${t}: ${fmt(v)}, ${pct.toFixed(2)} percent`);
      if(pct>=7) seg.innerHTML=`<b>${fmt(v)}</b>`;
      bindTip(seg,`${t} · ${fmt(v)} · ${pct.toFixed(pct<1?2:1)}%`);
      bar.appendChild(seg);
    });
    wrap.appendChild(bar); host.appendChild(wrap);
  });
}
