  }).join("");
  const role=HUE[t]?"":(HAYSTACK.has(t)?"haystack":(t==="unrecorded"?"n/a":"minor"));
  return `<tr><td><span class="sw" style="background:${colorOf(t)}"></span>${t}`+
    (role?` <span class="grp">${role}</span>`:"")+`</td>${cells}<td><b>${fmt(totals[t])}</b></td></tr>`;
}).join("");
</script>
