/* ---------- Sankey: measured object trail (project 23052) ---------- */
const SK=''' + data + ''';
(function(){
  const svg=document.getElementById("sk");
  const W=940,H=660,mT=26,mB=10,mL=6,mR=168,NW=11,GAP=2.5;
  const cols=SK.cols, nc=cols.length;
  const innerW=W-mL-mR, innerH=H-mT-mB;
  const xOf=i=>mL+i*(innerW-NW)/(nc-1);
  const total=20775;
  /* stable vertical order: by overall magnitude, haystack last */
  const mag={}; SK.nodes.forEach(n=>{for(const k in n) mag[k]=(mag[k]||0)+n[k];});
  const rank=Object.keys(mag).sort((a,b)=>{
    const ha=HAYSTACK.has(a),hb=HAYSTACK.has(b);
    if(ha!==hb) return ha?1:-1; return mag[b]-mag[a];});
  const pos={};                                  // pos[col][taxon]={y,h}
  SK.nodes.forEach((n,ci)=>{
    const keys=rank.filter(k=>n[k]);
    const gaps=GAP*Math.max(0,keys.length-1);
    const scale=(innerH-gaps)/total;
    let y=mT; pos[ci]={};
    keys.forEach(k=>{const h=Math.max(1.4,n[k]*scale); pos[ci][k]={y,h}; y+=h+GAP;});
