  const parts=[];
  /* column headers */
  cols.forEach((c,i)=>parts.push(
    `<text class="colhead" x="${xOf(i)}" y="${mT-11}">${c}</text>`));
  /* ribbons */
  ordered.forEach(l=>{
    const a=pos[l.c][l.a], b=pos[l.c+1][l.b];
    const sc=(innerH-GAP*Math.max(0,Object.keys(pos[l.c]).length-1))/total;
    const tc=(innerH-GAP*Math.max(0,Object.keys(pos[l.c+1]).length-1))/total;
    const th=Math.max(.8,l.v*sc), th2=Math.max(.8,l.v*tc);
    const ko=l.c+"|"+l.a+"|o", ki=(l.c+1)+"|"+l.b+"|i";
    const y0=a.y+off[ko], y1=b.y+off[ki];
    off[ko]+=th; off[ki]+=th2;
    const x0=xOf(l.c)+NW, x1=xOf(l.c+1), xm=(x0+x1)/2;
    const d=`M${x0},${y0} C${xm},${y0} ${xm},${y1} ${x1},${y1} L${x1},${y1+th2} `
           +`C${xm},${y1+th2} ${xm},${y0+th} ${x0},${y0+th} Z`;
    parts.push(`<path class="lk" data-a="${l.c}|${l.a}" data-b="${(l.c+1)}|${l.b}" `
      +`d="${d}" fill="${colorOf(l.a)}" opacity=".3"><title>${l.a} → ${l.b}: ${fmt(l.v)}</title></path>`);
  });
  /* nodes + labels */
  SK.nodes.forEach((n,ci)=>{
    for(const k in pos[ci]){
      const {y,h}=pos[ci][k];
      parts.push(`<rect class="nd" data-k="${ci}|${k}" x="${xOf(ci)}" y="${y}" width="${NW}" `
        +`height="${h}" rx="2" fill="${colorOf(k)}"><title>${k} · ${fmt(n[k])} at ${cols[ci]}</title></rect>`);
      if(h>=11){
        const last=ci===nc-1;
        const tx=last?xOf(ci)+NW+6:xOf(ci)+NW+5;
        if(last||h>=17)
          parts.push(`<text class="nlab" x="${tx}" y="${y+h/2-1}" dominant-baseline="middle">${k}`
            +` <tspan class="nval">${fmt(n[k])}</tspan></text>`);
      }
    }
  });
  svg.setAttribute("viewBox",`0 0 ${W} ${H}`);
  svg.innerHTML=parts.join("");
  /* hover: follow a cohort */
  const lks=[...svg.querySelectorAll(".lk")], nds=[...svg.querySelectorAll(".nd")];
  function focus(key){
    if(!key){svg.classList.remove("dim");lks.forEach(p=>p.classList.remove("on"));
      nds.forEach(r=>r.classList.remove("on"));return;}
    svg.classList.add("dim");
    const seen=new Set([key]); let frontier=[key];
    while(frontier.length){                       // walk forward through the trail
      const nxt=[];
      lks.forEach(p=>{ if(frontier.includes(p.dataset.a)&&!seen.has(p.dataset.b)){
        seen.add(p.dataset.b); nxt.push(p.dataset.b);} });
      frontier=nxt;
    }
    frontier=[key];
    while(frontier.length){                       // and backward
      const nxt=[];
      lks.forEach(p=>{ if(frontier.includes(p.dataset.b)&&!seen.has(p.dataset.a)){
        seen.add(p.dataset.a); nxt.push(p.dataset.a);} });
      frontier=nxt;
