    nds.forEach(r=>r.classList.toggle("on",seen.has(r.dataset.k)));
  }
  nds.forEach(r=>{
    r.addEventListener("pointerenter",()=>focus(r.dataset.k));
    r.addEventListener("pointerleave",()=>focus(null));
  });
  svg.addEventListener("pointerleave",()=>focus(null));
})();
