import json,urllib.request,time,sys
from concurrent.futures import ThreadPoolExecutor
cfg=json.load(open("/home/veit/PIScO_dev/process_pisco_profiles/process_pisco_profiles.config.example.json"))["ecotaxa"]
from ecotaxa_py_client import Configuration,ApiClient,AuthentificationApi,LoginReq,ObjectsApi,ProjectFilters
conf=Configuration(host=cfg["host"])
with ApiClient(conf) as ac:
    tok=AuthentificationApi(ac).login(LoginReq(username=cfg["username"],password=cfg["password"]))
conf.access_token=tok; H={"Authorization":f"Bearer {tok}"}
NC={}
def nm(c):
    if c is None: return None
    if c not in NC:
        try: NC[c]=json.load(urllib.request.urlopen(urllib.request.Request(cfg["host"]+f"/taxon/{c}",headers=H))).get('display_name')
        except Exception: NC[c]=str(c)
    return NC[c]
def grab(pid,out):
    with ApiClient(conf) as ac:
        cur=ObjectsApi(ac).get_object_set(pid,ProjectFilters(),
              fields="obj.objid,obj.classif_id,obj.classif_qual")
    CUR={d[0]:(d[1],d[2]) for d in cur.details}
    ids=list(CUR); print(f"[{pid}] objects={len(ids)}",flush=True)
    def hist(o):
        for _ in range(3):
            try: return o,json.load(urllib.request.urlopen(
                urllib.request.Request(cfg["host"]+f"/object/{o}/history",headers=H),timeout=40))
            except Exception: time.sleep(1)
        return o,None
    recs={}; t0=time.time()
    with ThreadPoolExecutor(max_workers=16) as ex:
        for i,(o,h) in enumerate(ex.map(hist,ids),1):
            if h is None: continue
            recs[o]={"final":nm(CUR[o][0]),"qual":CUR[o][1],
                     "hist":[[str(e.get("classif_date"))[:19],nm(e.get("classif_id")),
                              e.get("classif_qual"),e.get("classif_type")] for e in h]}
            if i%4000==0: print(f"  [{pid}] {i}/{len(ids)} {i/(time.time()-t0):.0f}/s",flush=True)
    json.dump(recs,open(out,"w"))
    print(f"[{pid}] WROTE {out}  n={len(recs)}  {(time.time()-t0)/60:.1f} min",flush=True)
grab(23052,sys.argv[1])
grab(23196,sys.argv[2])
print("ALL_DONE",flush=True)
