js='''
/* ---------- per-pass confusion matrices (validated objects only) ---------- */
const CMS=''' + cms + ''';
(function(){
  const host=document.getElementById("cms");
  host.innerHTML=CMS.map(m=>{
    const mx=Math.max(1,...m.cells.flat());
    const a=v=>v?0.07+0.88*(Math.log(v+1)/Math.log(mx+1)):0;
    const head=`<tr><th class="rh">predicted \\u2193 &nbsp;/&nbsp; expert \\u2192</th>`
      +m.cols.map(c=>`<th>${c}</th>`).join("")+`<th>row n</th><th>precision</th></tr>`;
    const body=m.rows.map((r,i)=>{
      const cells=m.cols.map((c,j)=>{
        const v=m.cells[i][j], dg=(c===r);
        if(!v) return `<td class="c zero">\\u2014</td>`;
        const al=a(v);
        return `<td class="c${al>0.55?" hi":""}${dg?" dg":""}" style="--a:${al.toFixed(3)}">`
              +`<i></i><span>${v.toLocaleString("en-US")}</span></td>`;
      }).join("");
      return `<tr><th class="rh">${r}</th>${cells}`
        +`<td class="pr">${m.rowtot[i].toLocaleString("en-US")}</td>`
        +`<td class="pr">${m.prec[i].toFixed(1)}%</td></tr>`;
    }).join("");
    return `<div class="cm">
      <div class="agree">agreement <b>${m.agree}%</b></div>
      <h3>${m.title}</h3><p class="sub">${m.sub}${m.avail?"":" · no Unknowns class available"}</p>
      <table><thead>${head}</thead><tbody>${body}</tbody></table></div>`;
  }).join("");
})();
'''
